/**
 * Transport for the management API (`/admin/api`). Every request, hand-written or
 * generated by Orval (through `mutator.ts`), goes through {@link apiFetch}, which owns:
 *   - `credentials: "include"` (the session cookie),
 *   - Spring Security's CSRF header on mutating methods,
 *   - `UnauthorizedError` on 401 and `ApiError` (parsed from RFC 9457) otherwise.
 */
export const API_BASE = "/admin/api";

export class UnauthorizedError extends Error {}

/** A non-2xx answer. `message` is the server's `detail`, shown to the user verbatim (FE-ACTION-3). */
export class ApiError extends Error {
  constructor(
    public status: number,
    message: string,
    /** The problem's machine-readable `code`, e.g. `"not_granted"`. */
    public code?: string,
    /** The full problem body, for fields beyond `detail`/`code`. */
    public body?: unknown,
  ) {
    super(message);
  }

  static async from(res: Response): Promise<ApiError> {
    let message = res.statusText || `Request failed (${res.status})`;
    let code: string | undefined;
    let body: unknown;
    try {
      const problem = await res.json();
      body = problem;
      if (typeof problem?.detail === "string") message = problem.detail;
      else if (typeof problem?.title === "string") message = problem.title;
      if (typeof problem?.code === "string") code = problem.code;
    } catch {
      /* not JSON: keep the status text */
    }
    return new ApiError(res.status, message, code, body);
  }
}

export function readCookie(name: string): string | null {
  const match = document.cookie.match(new RegExp("(?:^|; )" + name + "=([^;]*)"));
  return match ? decodeURIComponent(match[1]) : null;
}

/** Spring Security's `CookieCsrfTokenRepository` defaults. */
const CSRF_COOKIE = "XSRF-TOKEN";
const CSRF_HEADER = "X-XSRF-TOKEN";
const MUTATING = new Set(["POST", "PUT", "PATCH", "DELETE"]);

export async function apiFetch(path: string, init: RequestInit = {}): Promise<Response> {
  const method = (init.method ?? "GET").toUpperCase();
  const headers = new Headers(init.headers);
  headers.set("Accept", "application/json, application/problem+json");
  if (MUTATING.has(method)) {
    const csrf = readCookie(CSRF_COOKIE);
    if (csrf) headers.set(CSRF_HEADER, csrf);
  }
  const res = await fetch(`${API_BASE}${path}`, { ...init, method, headers, credentials: "include" });
  if (res.status === 401) throw new UnauthorizedError();
  if (!res.ok) throw await ApiError.from(res);
  return res;
}

export async function apiJson<T>(path: string, init?: RequestInit): Promise<T> {
  return (await apiFetch(path, init)).json() as Promise<T>;
}
